def split_nodes(state="hot", sub=OWN_DEPLOY):
    return [sh("gw", state)] + [sh(s, state, sub) for s in ("us", "ca", "or", "pa")]


def split_links(state="hot"):
    return [ln("gw", s, "to", 1200, state) for s in ("us", "ca", "or", "pa")]


